"use client";

import { forwardRef } from "react";
import { stripedPatternDefaults, type StripedPatternSpecProps } from "../generated/striped-pattern.types";
import { PatternShell, type PatternDivProps } from "../utils/pattern";

export interface StripedPatternProps extends StripedPatternSpecProps, Omit<PatternDivProps, keyof StripedPatternSpecProps> {}

/** Diagonal stripes that fill their parent. Decoration only: hidden from assistive technology, ignores the pointer. */
export const StripedPattern = forwardRef<HTMLDivElement, StripedPatternProps>(function StripedPattern(
  {
    size = stripedPatternDefaults.size,
    gap = stripedPatternDefaults.gap,
    angle = stripedPatternDefaults.angle,
    color = stripedPatternDefaults.color,
    fade = stripedPatternDefaults.fade,
    animated = stripedPatternDefaults.animated,
    isStill = stripedPatternDefaults.isStill,
    duration = stripedPatternDefaults.duration,
    ...rest
  },
  ref,
) {
  const period = size + gap;
  const rad = (angle * Math.PI) / 180;
  // Moving one period along the gradient direction repeats the stripes exactly, so the loop has no jump.
  const travel: [number, number] = [Math.round(Math.sin(rad) * period * 100) / 100, Math.round(-Math.cos(rad) * period * 100) / 100];
  return (
    <PatternShell
      {...rest}
      ref={ref}
      color={color}
      fade={fade}
      animated={animated}
      isStill={isStill}
      duration={duration}
      period={period}
      travel={travel}
      fill={{ backgroundImage: `repeating-linear-gradient(${angle}deg, var(--rdm-pc) 0 ${size}px, transparent ${size}px ${period}px)` }}
    />
  );
});

// Generated by rdloom codegen from specs/striped-pattern.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

/** Diagonal stripes that fill their parent, with an optional edge fade and a slow drift along the stripes. */
export interface StripedPatternSpecProps {
  /**
   * Stripe width in pixels.
   * @default 2
   */
  size?: number;
  /**
   * Space between stripes in pixels.
   * @default 10
   */
  gap?: number;
  /**
   * Stripe direction in degrees.
   * @default 45
   */
  angle?: number;
  /**
   * Colour of the pattern: any CSS colour or a token such as var(--rd-color-border-default).
   * @default "color-mix(in srgb, var(--rd-color-text-default) 16%, transparent)"
   */
  color?: string;
  /**
   * Fades the pattern out toward its edges.
   * @default true
   */
  fade?: boolean;
  /**
   * Drifts the pattern slowly, one tile per cycle. Off by default.
   * @default false
   */
  animated?: boolean;
  /**
   * Stops the drift. Moving content should be stoppable.
   * @default false
   */
  isStill?: boolean;
  /**
   * Seconds one drift cycle takes.
   * @default 6
   */
  duration?: number;
}

export const stripedPatternDefaults = {
  size: 2,
  gap: 10,
  angle: 45,
  color: "color-mix(in srgb, var(--rd-color-text-default) 16%, transparent)",
  fade: true,
  animated: false,
  isStill: false,
  duration: 6,
} as const;

export const stripedPatternMeta = {
  "name": "StripedPattern",
  "version": "0.1.0",
  "status": "experimental",
  "role": "presentation"
} as const;
